1	package dashboard
2	
3	import (
4		"context"
5		"encoding/json"
6		"net/http"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync"
12	
13		"github.com/integrio-intropy/intropy-cli/internal/template"
14		"github.com/integrio-intropy/intropy-cli/internal/topology"
15	)
16	
17	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
18	// the detail endpoint returns, so a huge file cannot bloat a response.
19	const maxDocBytes = 128 * 1024
20	
21	// apiServer holds the request-independent state for the JSON API.
22	type apiServer struct {
23		root    string
24		version string
25		topo    topologyProvider
26	
27		// topoMu guards the cached provider result. Fetching runs the hosts'
28		// graph verbs (a dotnet build on first run), so the result is computed
29		// once — on the first /api/topology request — and reused until an
30		// explicit refresh.
31		topoMu     sync.Mutex
32		topoLoaded bool
33		topoCache  topologyReport
34	}
35	
36	// topologyReport is the /api/topology payload: every declared topology plus
37	// the per-host failures the UI renders. Topologies is always an array (never
38	// null) even when empty.
39	type topologyReport struct {
40		Topologies []topology.Entry `json:"topologies"`
41		Errors     []string         `json:"errors,omitempty"`
42	}
43	
44	// fileDoc is a text document surfaced in an integration's detail view.
45	type fileDoc struct {
46		Name    string `json:"name"`
47		Content string `json:"content"`
48	}
49	
50	// integrationSummary is a scaffold entry plus the coordinates the sidebar
51	// tree groups by: Name is the directory that carries the .intropy record.
52	// System is the name a sibling system-host scaffold declares for the
53	// directory's parent, falling back to the parent folder's name; Domain is the
54	// system's parent folder. Absent a host, System is empty when the integration
55	// sits directly under the workspace root, and Domain is empty when the
56	// system does.
57	type integrationSummary struct {
58		template.ScaffoldEntry
59		Name   string `json:"name"`
60		System string `json:"system,omitempty"`
61		Domain string `json:"domain,omitempty"`
62	}
63	
64	// integrationDetail is a single integration plus best-effort, on-disk
65	// enrichment. Every enrichment field is optional and absent when the
66	// corresponding file or directory does not exist.
67	type integrationDetail struct {
68		integrationSummary
69		Agents        *fileDoc        `json:"agents,omitempty"`
70		Readme        *fileDoc        `json:"readme,omitempty"`
71		Components    []DaprComponent `json:"components,omitempty"`
72		PipelineSteps []string        `json:"pipelineSteps,omitempty"`
73	}
74	
75	// newHandler wires the API routes and the SPA static handler onto a mux.
76	func newHandler(root, version string, topo topologyProvider) (http.Handler, error) {
77		api := &apiServer{root: root, version: version, topo: topo}
78		static, err := staticHandler()
79		if err != nil {
80			return nil, err
81		}
82	
83		mux := http.NewServeMux()
84		mux.HandleFunc("GET /api/health", api.health)
85		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
86		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
87		mux.HandleFunc("GET /api/flow", api.flow)
88		mux.HandleFunc("GET /api/topology", api.topologies)
89		mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
90		mux.Handle("/", static)
91		return mux, nil
92	}
93	
94	func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
95		writeJSON(w, http.StatusOK, map[string]string{
96			"status":  "ok",
97			"version": s.version,
98		})
99	}
100	
101	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
102	// the same order — with the derived name/system fields added on top and each
103	// Path normalized to a root-relative identifier. The response is always an
104	// array (never null) even when empty.
105	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
106		entries, systems := s.scan()
107		summaries := make([]integrationSummary, 0, len(entries))
108		for _, e := range entries {
109			summaries = append(summaries, s.summarize(e, systems))
110		}
111		writeJSON(w, http.StatusOK, summaries)
112	}
113	
114	// scan splits the workspace's scaffold entries for the API: the integration
115	// blocks to catalog, plus the declared systems keyed by their root directory
116	// (the directory holding a system-host scaffold). Support projects — the host
117	// and its shared contracts library — are infrastructure the system view
118	// already represents, not integrations to list.
119	func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
120		entries, _ := template.ListScaffolds(s.root)
121		systems = map[string]string{}
122		for _, e := range entries {
123			if e.Role == template.RoleSystemHost {
124				systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
125			}
126		}
127		blocks = entries[:0]
128		for _, e := range entries {
129			if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
130				continue
131			}
132			blocks = append(blocks, e)
133		}
134		return blocks, systems
135	}
136	
137	// systemName is the name a system-host scaffold declares for its system
138	// (the template's `name` value, recorded at `sys create`), falling back to
139	// the host's parent directory name.
140	func systemName(host template.ScaffoldEntry) string {
141		if name, ok := host.Values["name"].(string); ok && name != "" {
142			return name
143		}
144		dir := filepath.Dir(host.Path)
145		if abs, err := filepath.Abs(dir); err == nil {
146			dir = abs
147		}
148		return filepath.Base(dir)
149	}
150	
151	// summarize derives an entry's tree coordinates from its path and the
152	// declared systems. A sibling system-host makes membership explicit: its
153	// declared name wins over the folder-derived one and applies even directly
154	// under the workspace root (where no folder-derived system exists).
155	// Otherwise the workspace root itself never counts as a system or domain, so
156	// an integration scaffolded at the root has neither and one directly under
157	// the root has a system but no domain. The served Path is made root-relative
158	// so it is a stable, URL-safe identifier regardless of whether the command
159	// was given a relative or absolute root (an absolute path would otherwise
160	// break detail lookups).
161	func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
162		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
163		sum.Path = s.relPath(e.Path)
164		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
165		parent := filepath.Dir(path)
166		if declared, ok := systems[parent]; ok && path != root {
167			sum.System = declared
168			if grand := filepath.Dir(parent); parent != root && grand != root {
169				sum.Domain = filepath.Base(grand)
170			}
171			return sum
172		}
173		if path == root || parent == root {
174			return sum
175		}
176		sum.System = filepath.Base(parent)
177		if grand := filepath.Dir(parent); grand != root {
178			sum.Domain = filepath.Base(grand)
179		}
180		return sum
181	}
182	
183	// relPath turns an entry's on-disk path into the root-relative, slash-separated
184	// identifier used in API responses and URLs. It falls back to the cleaned path
185	// so a value is always produced even if Rel fails (e.g. differing volumes).
186	func (s *apiServer) relPath(p string) string {
187		if rel, err := filepath.Rel(s.root, p); err == nil {
188			return filepath.ToSlash(rel)
189		}
190		return filepath.ToSlash(filepath.Clean(p))
191	}
192	
193	// flow returns every integration enriched with the pipeline steps and Dapr
194	// components the flow canvas draws, so the whole graph loads in one request.
195	// It reuses integrationDetail but leaves the document fields (agents/readme)
196	// nil — the canvas nodes do not render them.
197	func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
198		entries, systems := s.scan()
199		nodes := make([]integrationDetail, 0, len(entries))
200		for _, e := range entries {
201			dir := e.Path
202			nodes = append(nodes, integrationDetail{
203				integrationSummary: s.summarize(e, systems),
204				Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
205				PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
206			})
207		}
208		writeJSON(w, http.StatusOK, nodes)
209	}
210	
211	// topologies returns every system topology declared by a host's graph verb,
212	// each Path normalized to the same root-relative identifier integration
213	// paths use, so the flow canvas can match a topology to the integrations
214	// living beside its host. The provider result is cached after the first
215	// request (the verb builds the host); POST /api/topology/refresh recomputes.
216	func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
217		writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
218	}
219	
220	// refreshTopologies recomputes the topology cache by re-running every host's
221	// graph verb, then returns the fresh report.
222	func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
223		writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
224	}
225	
226	// topologyReport returns the cached provider result, computing it on first
227	// use or when force is set. Concurrent requests share one computation.
228	func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
229		s.topoMu.Lock()
230		defer s.topoMu.Unlock()
231		if s.topoLoaded && !force {
232			return s.topoCache
233		}
234		entries, errs := s.topo(ctx)
235		report := topologyReport{Topologies: make([]topology.Entry, 0, len(entries)), Errors: errs}
236		for _, e := range entries {
237			e.Path = s.relPath(e.Path)
238			report.Topologies = append(report.Topologies, e)
239		}
240		s.topoCache, s.topoLoaded = report, true
241		return report
242	}
243	
244	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
245		want := strings.Trim(r.PathValue("path"), "/")
246		// An integration at the workspace root has the identifier "." (see
247		// relPath), but a browser strips the "." segment from /api/integrations/.
248		// so it arrives empty — treat the two as the same request.
249		if want == "" {
250			want = "."
251		}
252		entries, systems := s.scan()
253		for _, e := range entries {
254			if s.relPath(e.Path) == want {
255				writeJSON(w, http.StatusOK, s.enrich(e, systems))
256				return
257			}
258		}
259		writeError(w, http.StatusNotFound, "integration not found: "+want)
260	}
261	
262	// enrich reads optional on-disk context for an integration. The entry's Path
263	// is already usable from the process working directory (see ListScaffolds), so
264	// it doubles as the project directory.
265	func (s *apiServer) enrich(e template.ScaffoldEntry, systems map[string]string) integrationDetail {
266		dir := e.Path
267		return integrationDetail{
268			integrationSummary: s.summarize(e, systems),
269			Agents:             readDoc(dir, "AGENTS.md"),
270			Readme:             readDoc(dir, "README.md"),
271			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
272			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
273		}
274	}
275	
276	// readDoc returns the named text file's (possibly truncated) contents, or nil
277	// if it is absent or unreadable.
278	func readDoc(dir, name string) *fileDoc {
279		data, err := os.ReadFile(filepath.Join(dir, name))
280		if err != nil {
281			return nil
282		}
283		if len(data) > maxDocBytes {
284			data = data[:maxDocBytes]
285		}
286		return &fileDoc{Name: name, Content: string(data)}
287	}
288	
289	// listNames returns the sorted base names of the files directly under dir, or
290	// nil if dir is absent or unreadable.
291	func listNames(dir string) []string {
292		ents, err := os.ReadDir(dir)
293		if err != nil {
294			return nil
295		}
296		var names []string
297		for _, ent := range ents {
298			if !ent.IsDir() {
299				names = append(names, ent.Name())
300			}
301		}
302		sort.Strings(names)
303		return names
304	}
305	
306	func writeJSON(w http.ResponseWriter, status int, v any) {
307		w.Header().Set("Content-Type", "application/json; charset=utf-8")
308		w.WriteHeader(status)
309		enc := json.NewEncoder(w)
310		enc.SetIndent("", "  ")
311		_ = enc.Encode(v)
312	}
313	
314	func writeError(w http.ResponseWriter, status int, msg string) {
315		writeJSON(w, status, map[string]string{"error": msg})
316	}
317

1	package topology
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	const validRecord = `{
9	  "apiVersion": "topology.intropy.io/v1",
10	  "kind": "SystemTopology",
11	  "system": "distribution",
12	  "components": [
13	    {
14	      "name": "extractor",
15	      "kind": "extractor",
16	      "subscribes": [],
17	      "publishes": [
18	        {"port": "b2c", "pubsub": "price-pubsub", "topic": "price-b2c"},
19	        {"port": "b2b", "pubsub": "price-pubsub", "topic": "price-b2b"}
20	      ],
21	      "connectors": [{"connector": "price-master", "direction": "in"}]
22	    },
23	    {
24	      "name": "erp-loader",
25	      "kind": "loader",
26	      "subscribes": [{"pubsub": "price-pubsub", "topic": "price-b2b"}],
27	      "connectors": [{"connector": "erp", "direction": "out"}]
28	    }
29	  ],
30	  "topics": [
31	    {"pubsub": "price-pubsub", "topic": "price-b2b", "contract": "Price.Contracts.B2BPrice",
32	     "publishers": ["extractor"], "subscribers": ["erp-loader"]},
33	    {"pubsub": "price-pubsub", "topic": "price-b2c", "contract": "Price.Contracts.B2CPrice",
34	     "publishers": ["extractor"], "subscribers": ["wms-loader"]}
35	  ],
36	  "connectors": [
37	    {"name": "erp", "externalSystem": "erp",
38	     "transport": {"type": "http", "supportsInput": false, "supportsOutput": true},
39	     "directions": ["out"], "usedBy": ["erp-loader"]},
40	    {"name": "price-master", "externalSystem": "price-master",
41	     "transport": {"type": "sftp", "supportsInput": true, "supportsOutput": true},
42	     "directions": ["in"], "usedBy": ["extractor"]}
43	  ]
44	}`
45	
46	func TestDecodeValid(t *testing.T) {
47		got, err := Decode(strings.NewReader(validRecord))
48		if err != nil {
49			t.Fatalf("Decode: %v", err)
50		}
51		if got.System != "distribution" {
52			t.Errorf("system = %q, want %q", got.System, "distribution")
53		}
54		if got.Kind != Kind {
55			t.Errorf("kind = %q, want %q", got.Kind, Kind)
56		}
57		if len(got.Components) != 2 || len(got.Topics) != 2 || len(got.Connectors) != 2 {
58			t.Fatalf("entity counts = %d/%d/%d, want 2/2/2",
59				len(got.Components), len(got.Topics), len(got.Connectors))
60		}
61		if c := got.Components[0]; c.Kind != "extractor" || len(c.Publishes) != 2 {
62			t.Fatalf("extractor = %+v", c)
63		}
64		if p := got.Components[0].Publishes[0]; p.Port != "b2c" || p.PubSub != "price-pubsub" || p.Topic != "price-b2c" {
65			t.Errorf("publish = %+v", p)
66		}
67		if u := got.Components[0].Connectors[0]; u.Connector != "price-master" || u.Direction != "in" {
68			t.Errorf("connector use = %+v", u)
69		}
70		if s := got.Components[1].Subscribes[0]; s.PubSub != "price-pubsub" || s.Topic != "price-b2b" {
71			t.Errorf("subscribe = %+v", s)
72		}
73		if tp := got.Topics[0]; tp.Topic != "price-b2b" || tp.Contract != "Price.Contracts.B2BPrice" {
74			t.Errorf("topic = %+v", tp)
75		}
76		if cn := got.Connectors[1]; cn.Name != "price-master" || cn.Transport.Type != "sftp" ||
77			!cn.Transport.SupportsInput || !cn.Transport.SupportsOutput {
78			t.Errorf("connector = %+v", cn)
79		}
80	}
81	
82	func TestDecodeMalformed(t *testing.T) {
83		if _, err := Decode(strings.NewReader("{not json")); err == nil ||
84			!strings.Contains(err.Error(), "parse topology record") {
85			t.Fatalf("err = %v, want parse error", err)
86		}
87	}
88	
89	// A host that prints build noise before the JSON violates the stdout contract
90	// and must be rejected, not guessed at.
91	func TestDecodeLeadingNoiseIsRejected(t *testing.T) {
92		if _, err := Decode(strings.NewReader("Restoring packages...\n" + validRecord)); err == nil {
93			t.Fatal("expected error for non-JSON prefix, got nil")
94		}
95	}
96	
97	// An unknown apiVersion is surfaced as an error, not guessed at.
98	func TestDecodeUnsupportedAPIVersion(t *testing.T) {
99		if _, err := Decode(strings.NewReader(`{"apiVersion": "topology.intropy.io/v99", "system": "x"}`)); err == nil ||
100			!strings.Contains(err.Error(), "unsupported topology apiVersion") {
101			t.Fatalf("err = %v, want unsupported apiVersion error", err)
102		}
103	}
104	
105	// An old-schema record (integer schemaVersion, system as an object) is
106	// rejected rather than mis-parsed. It fails at unmarshal (system is not a
107	// string) before the apiVersion check, which is still a rejection — the
108	// guarantee is that Decode never silently accepts it.
109	func TestDecodeOldSchemaIsRejected(t *testing.T) {
110		if _, err := Decode(strings.NewReader(`{"schemaVersion": 1, "system": {"name": "x"}}`)); err == nil {
111			t.Fatal("expected error for old-schema record, got nil")
112		}
113	}
114

